 * <collapsible-panel> — a disclosure-style collapsible panel.
 *
 * Attributes:
 *  - heading: text used as the toggle button label.
 *  - open: boolean attribute; present = expanded.
 *
 * Shadow DOM structure:
 *  <button part="heading" aria-expanded aria-controls="content">…</button>
 *  <div id="content" part="content" ?hidden><slot></slot></div>
 *
 * Events:
 *  - "toggle" (bubbles, composed) dispatched whenever open state changes,
 *    regardless of whether the change came from user interaction or from
 *    setting/removing the `open` attribute programmatically.
 */
export class CollapsiblePanel extends HTMLElement {
  static observedAttributes = ['open'];

  #button;
  #region;
  #open = false;

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });

    const button = document.createElement('button');
    button.type = 'button';
    button.part = 'heading';
    button.setAttribute('aria-controls', 'content');
    button.addEventListener('click', () => this.#userToggle());
    // Enter/Space activate a <button> natively in real browsers; we also
    // handle keydown explicitly so synthetic KeyboardEvents (and any
    // environment without native button activation semantics) work too.
    button.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ' || e.key === 'Spacebar') {
        e.preventDefault();
        this.#userToggle();
      }
    });

    const region = document.createElement('div');
    region.id = 'content';
    region.part = 'content';
    const slot = document.createElement('slot');
    region.appendChild(slot);

    this.shadowRoot.append(button, region);
    this.#button = button;
    this.#region = region;
    this.#render();
  }

  /** Heading text shown on the disclosure button. */
  get heading() {
    return this.getAttribute('heading') ?? '';
  }

  set heading(value) {
    if (value == null) this.removeAttribute('heading');
    else this.setAttribute('heading', value);
  }

  /** Expanded state. Reflects the `open` attribute in both directions. */
  get open() {
    return this.hasAttribute('open');
  }

  set open(value) {
    // Boolean reflection semantics per HTML spec.
    if (value) this.setAttribute('open', '');
    else this.removeAttribute('open');
  }

  /**
   * Only called for `open` — the one observed attribute. Handles changes
   * arriving at any time, including before connection and after upgrade.
   */
  attributeChangedCallback(name, oldValue, newValue) {
    if (name !== 'open') return;
    const wasOpen = this.#open;
    this.#open = newValue !== null;
    if (wasOpen !== this.#open) {
      this.#render();
      this.#dispatchToggle();
    }
  }

  connectedCallback() {
    // Upgrade-time safety net: make sure the rendered state matches the
    // attribute even if attributeChangedCallback ran before children existed.
    this.#render();
  }

  /** Toggle triggered by user interaction (click / Enter / Space). */
  #userToggle() {
    // Mutating the attribute is the single source of truth:
    // attributeChangedCallback performs the render + event dispatch.
    this.open = !this.#open;
  }

  #render() {
    this.#button.textContent = this.heading;
    this.#button.setAttribute('aria-expanded', String(this.#open));
    if (this.#open) this.#region.removeAttribute('hidden');
    else this.#region.setAttribute('hidden', '');
  }

  #dispatchToggle() {
    this.dispatchEvent(
      new CustomEvent('toggle', {
        bubbles: true,
        composed: true,
        detail: { open: this.#open },
      })
    );
  }
}

if (!customElements.get('collapsible-panel')) {
  customElements.define('collapsible-panel', CollapsiblePanel);
}
