result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/wc-panel/test/collapsible-panel.test.js", "content": "import { describe, it, expect, beforeEach } from 'vitest';
import { CollapsiblePanel } from '../src/collapsible-panel.js';
import './setup.js';

function makePanel({ heading = 'Details', lightDom = '' } = {}) {
  const panel = document.createElement('collapsible-panel');
  if (heading != null) panel.setAttribute('heading', heading);
  // Light DOM content via innerHTML so slotted children stay in the host.
  if (lightDom) panel.innerHTML = lightDom;
  document.body.appendChild(panel);
  return panel;
}

const shadowButton = (panel) => panel.shadowRoot.querySelector('button');
const shadowRegion = (panel) => panel.shadowRoot.querySelector('#content');

beforeEach(() => {
  document.body.innerHTML = '';
});

describe('<collapsible-panel>', () => {
  it('is registered as a custom element extending HTMLElement', () => {
    expect(customElements.get('collapsible-panel')).toBe(CollapsiblePanel);
    const panel = makePanel();
    expect(panel).toBeInstanceOf(CollapsiblePanel);
    expect(panel).toBeInstanceOf(HTMLElement);
  });

  describe('initial state & shadow structure', () => {
    it('renders a button and a hidden content region by default', () => {
      const panel = makePanel();
      expect(shadowButton(panel)).toBeTruthy();
      expect(shadowRegion(panel)).toBeTruthy();
      expect(panel.hasAttribute('open')).toBe(false);
      expect(shadowRegion(panel).hasAttribute('hidden')).toBe(true);
    });

    it('uses the heading attribute as the button label', () => {
      const panel = makePanel({ heading: 'More info' });
      expect(shadowButton(panel).textContent).toBe('More info');
    });

    it('starts open when the open attribute is present before upgrade', () => {
      const panel = makePanel({ lightDom: '<p>hi</p>' });
      panel.setAttribute('open', '');
      // Force re-parse scenario: re-create via template-like clone path
      const fresh = document.createElement('collapsible-panel');
      fresh.setAttribute('open', '');
      document.body.appendChild(fresh);
      expect(fresh.open).toBe(true);
      expect(shadowButton(fresh).getAttribute('aria-expanded')).toBe('true');
      expect(shadowRegion(fresh).hasAttribute('hidden')).toBe(false);
      panel.remove();
    });
  });

  describe('disclosure semantics (ARIA wiring)', () => {
    it('button has aria-controls pointing at the region id', () => {
      const panel = makePanel();
      const button = shadowButton(panel);
      const region = shadowRegion(panel);
      expect(button.getAttribute('aria-controls')).toBe(region.id);
      expect(region.id).toBe('content');
    });

    it('aria-expanded is exactly "false" when closed and "true" when open', () => {
      const panel = makePanel();
      const button = shadowButton(panel);
      expect(button.getAttribute('aria-expanded')).toBe('false');
      panel.setAttribute('open', '');
      expect(button.getAttribute('aria-expanded')).toBe('true');
      panel.removeAttribute('open');
      expect(button.getAttribute('aria-expanded')).toBe('false');
    });

    it('visible state is conveyed by the hidden attribute on the region', () => {
      const panel = makePanel();
      expect(shadowRegion(panel).hasAttribute('hidden')).toBe(true);
      panel.setAttribute('open', '');
      expect(shadowRegion(panel).hasAttribute('hidden')).toBe(false);
      panel.removeAttribute('open');
      expect(shadowRegion(panel).hasAttribute('hidden')).toBe(true);
    });
  });

  describe('attribute reflection — programmatic -> UI', () => {
    it('setting the open attribute programmatically opens the panel', () => {
      const panel = makePanel();
      panel.setAttribute('open', '');
      expect(panel.open).toBe(true);
      expect(shadowButton(panel).getAttribute('aria-expanded')).toBe('true');
      expect(shadowRegion(panel).hasAttribute('hidden')).toBe(false);
    });

    it('removing the attribute closes the panel', () => {
      const panel = makePanel();
      panel.setAttribute('open', '');
      panel.removeAttribute('open');
      expect(panel.open).toBe(false);
      expect(shadowButton(panel).getAttribute('aria-expanded')).toBe('false');
      expect(shadowRegion(panel).hasAttribute('hidden')).toBe(true);
    });

    it('IDL property reflects both ways (set property -> attribute appears)', () => {
      const panel = makePanel();
      panel.open = true;
      expect(panel.hasAttribute('open')).toBe(true);
      panel.open = false;
      expect(panel.hasAttribute('open')).toBe(false);
    });

    it('reacts to the open attribute changing after connection', async () => {
      const panel = makePanel();
      await Promise.resolve(); // ensure connected
      // Flip the attribute long after connection, as observedAttributes must handle.
      panel.setAttribute('open', '');
      expect(shadowButton(panel).getAttribute('aria-expanded')).toBe('true');
      panel.removeAttribute('open');
      expect(shadowButton(panel).getAttribute('aria-expanded')).toBe('false');
    });
  });

  describe('user interaction -> attribute reflection', () => {
    it('clicking the button toggles open and updates the attribute', () => {
      const panel = makePanel();
      shadowButton(panel).click();
      expect(panel.hasAttribute('open')).toBe(true);
      expect(shadowButton(panel).getAttribute('aria-expanded')).toBe('true');
      expect(shadowRegion(panel).hasAttribute('hidden')).toBe(false);

      shadowButton(panel).click();
      expect(panel.hasAttribute('open')).toBe(false);
      expect(shadowButton(panel).getAttribute('aria-expanded')).toBe('false');
      expect(shadowRegion(panel).hasAttribute('hidden')).toBe(true);
    });

    it('Enter key on the button toggles the panel', () => {
      const panel = makePanel();
      const button = shadowButton(panel);
      button.focus();
      button.dispatchEvent(
        new KeyboardEvent('keydown', { key: 'Enter', bubbles: true, composed: true })
      );
      expect(panel.hasAttribute('open')).toBe(true);
      expect(button.getAttribute('aria-expanded')).toBe('true');

      button.dispatchEvent(
        new KeyboardEvent('keydown', { key: 'Enter', bubbles: true, composed: true })
      );
      expect(panel.hasAttribute('open')).toBe(false);
    });

    it('Space key on the button toggles the panel', () => {
      const panel = makePanel();
      const button = shadowButton(panel);
      for (const key of [' ', 'Spacebar']) {
        button.dispatchEvent(
          new KeyboardEvent('keydown', { key, bubbles: true, composed: true })
        );
      }
      // Two toggles -> back to closed.
      expect(panel.hasAttribute('open')).toBe(false);
    });

    it('keyboard events on other keys do not toggle', () => {
      const panel = makePanel();
      shadowButton(panel).dispatchEvent(
        new KeyboardEvent('keydown', { key: 'Tab', bubbles: true })
      );
      shadowButton(panel).dispatchEvent(
        new KeyboardEvent('keydown', { key: 'a', bubbles: true })
      );
      expect(panel.hasAttribute('open')).toBe(false);
    });
  });

  describe('toggle events', () => {
    it('dispatches a toggle event when opened/closed by click', () => {
      const panel = makePanel();
      const events = [];
      panel.addEventListener('toggle', (e) =>
        events.push({ type: e.type, open: e.detail.open })
      );
      shadowButton(panel).click();
      shadowButton(panel).click();
      expect(events).toEqual([
        { type: 'toggle', open: true },
        { type: 'toggle', open: false },
      ]);
    });

    it('dispatches toggle when the attribute changes programmatically', () => {
      const panel = makePanel();
      const events = [];
      panel.addEventListener('toggle', (e) => events.push(e.detail.open));
      panel.setAttribute('open', '');
      panel.removeAttribute('open');
      expect(events).toEqual([true, false]);
    });

    it('does not dispatch toggle for redundant attribute sets', () => {
      const panel = makePanel();
      panel.setAttribute('open', '');
      const events = [];
      panel.addEventListener('toggle', (e) => events.push(e));
      panel.setAttribute('open', ''); // already open
      panel.removeAttribute('open');
      panel.removeAttribute('open'); // already closed
      expect(events.length).toBe(1);
    });

    it('toggle event bubbles and crosses the shadow boundary', () => {
      const panel = makePanel();
      let seen = 0;
      document.body.addEventListener('toggle', () => seen++);
      shadowButton(panel).click();
      expect(seen).toBe(1);
    });
  });

  describe('slotted light-DOM content', () => {
    it('keeps children in the light DOM of the host', () => {
      const panel = makePanel({ lightDom: '<p id="body-text">Hello</p>' });
      const p = panel.querySelector('#body-text');
      // Must still be a light-DOM child of the host element itself...
      expect(p.parentElement).toBe(panel);
      // ...not cloned/moved into the shadow root.
      expect(panel.shadowRoot.getElementById('body-text')).toBeNull();
      expect(panel.shadowRoot.querySelectorAll('*').length).toBeLessThan(4);
    });

    it('distributes content through the slot regardless of open state', () => {
      const panel = makePanel({ lightDom: '<span>content</span>' });
      const slot = panel.shadowRoot.querySelector('slot');
      expect(slot.assignedElements().map((n) => n.textContent)).toEqual(['content']);
      panel.setAttribute('open', '');
      expect(slot.assignedElements().length).toBe(1);
    });

    it('toggling visibility does not detach or mutate slotted children', () => {
      const panel = makePanel({ lightDom: '<ul><li>one</li></ul>' });
      const ul = panel.querySelector('ul');
      shadowButton(panel).click();
      shadowButton(panel).click();
      expect(panel.querySelector('ul')).toBe(ul);
      expect(ul.isConnected).toBe(true);
    });
  });
});
"})
